const now = new Date();
const daysLookback = $json.DAYS_LOOKBACK || 7;
const sinceDate = new Date(now.getTime() - (daysLookback * 24 * 60 * 60 * 1000));

return {
  ...$json,
  sinceISO: sinceDate.toISOString(),
  untilISO: now.toISOString(),
  startDateStr: sinceDate.toISOString().split('T')[0],
  endDateStr: now.toISOString().split('T')[0]
};

const cfg = $('Calculate Date Window').first().json;
const sinceTime = new Date(cfg.sinceISO).getTime();

// 1. Commits normalization
const rawCommits = $('Fetch Commits').all().map(i => i.json);
const commitsList = Array.isArray(rawCommits[0]) ? rawCommits[0] : rawCommits;
const commits = commitsList
  .filter(c => c && c.sha)
  .map(c => ({
    sha: c.sha ? c.sha.substring(0, 7) : '',
    author: (c.author && c.author.login) || (c.commit && c.commit.author && c.commit.author.name) || 'Unknown',
    message: c.commit && c.commit.message ? c.commit.message.split('\n')[0] : '',
    date: c.commit && c.commit.author ? c.commit.author.date : ''
  }));

// 2. Merged PRs filtering (only merged within the week window)
const rawPulls = $('Fetch Closed Pull Requests').all().map(i => i.json);
const pullsList = Array.isArray(rawPulls[0]) ? rawPulls[0] : rawPulls;
const mergedPRs = pullsList
  .filter(pr => pr && pr.merged_at && new Date(pr.merged_at).getTime() >= sinceTime)
  .map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user ? pr.user.login : 'Unknown',
    merged_at: pr.merged_at,
    url: pr.html_url
  }));

// 3. Closed Issues (exclude PRs since GitHub issues API returns both)
const rawIssues = $('Fetch Closed Issues').all().map(i => i.json);
const issuesList = Array.isArray(rawIssues[0]) ? rawIssues[0] : rawIssues;
const closedIssues = issuesList
  .filter(issue => issue && !issue.pull_request && issue.state === 'closed' && new Date(issue.closed_at).getTime() >= sinceTime)
  .map(issue => ({
    number: issue.number,
    title: issue.title,
    author: issue.user ? issue.user.login : 'Unknown',
    closed_at: issue.closed_at,
    url: issue.html_url
  }));

const language = (cfg.SUMMARY_LANGUAGE || 'EN').toUpperCase();

const promptInstruction = language === 'FR'
  ? 'Rédigez un résumé exécutif hebdomadaire clair et professionnel en français pour l\'équipe technique.'
  : 'Provide a crisp, executive-ready weekly engineering summary in English for leadership and developers.';

const systemPrompt = `You are a Principal Tech Lead and Engineering Communications Expert. ${promptInstruction}
Your summary must be structured with:
1. 🚀 Executive Overview (high-level impact & velocity)
2. ✨ Key Features & Merged Pull Requests (grouped by theme)
3. 🐛 Bug Fixes & Resolved Issues
4. 📈 Git Activity & Contributors
5. 🎯 Next Week Priorities & Focus Areas
Keep it concise, actionable, and formatted cleanly in Markdown. Do not include meta filler.`;

const userContent = JSON.stringify({
  repository: `${cfg.GITHUB_OWNER}/${cfg.GITHUB_REPO}`,
  period: `${cfg.startDateStr} to ${cfg.endDateStr}`,
  stats: {
    total_commits: commits.length,
    total_merged_prs: mergedPRs.length,
    total_closed_issues: closedIssues.length
  },
  merged_pull_requests: mergedPRs,
  closed_issues: closedIssues,
  commits: commits.slice(0, 50)
}, null, 2);

return {
  ...cfg,
  stats: {
    commitsCount: commits.length,
    prsCount: mergedPRs.length,
    issuesCount: closedIssues.length
  },
  systemPrompt,
  userContent,
  claudePayload: {
    model: cfg.CLAUDE_MODEL || 'claude-sonnet-4-20250514',
    max_tokens: 3000,
    system: systemPrompt,
    messages: [
      {
        role: 'user',
        content: `Summarize the following development activity for ${cfg.GITHUB_OWNER}/${cfg.GITHUB_REPO} for the week of ${cfg.startDateStr} to ${cfg.endDateStr}:\n\n${userContent}`
      }
    ]
  }
};

const prev = $('Aggregate & Format Prompt').first().json;
const claudeResponse = $json;

let narrativeText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  narrativeText = claudeResponse.content.map(c => c.text || '').join('\n\n');
} else if (claudeResponse.text) {
  narrativeText = claudeResponse.text;
} else {
  narrativeText = 'No response text received from Claude API.';
}

const titleHeader = `📊 **Weekly Dev Summary: ${prev.GITHUB_OWNER}/${prev.GITHUB_REPO}** (${prev.startDateStr} - ${prev.endDateStr})`;
const fullReportMarkdown = `${titleHeader}\n\n${narrativeText}`;

// Discord webhook formatting (content length limitation handling)
const discordContent = fullReportMarkdown.length > 1950
  ? `${fullReportMarkdown.substring(0, 1900)}...\n\n*(Report truncated for Discord character limits. See email or repository logs for full details.)*`
  : fullReportMarkdown;

// Slack webhook payload
const slackPayload = {
  text: titleHeader,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `Weekly Dev Summary: ${prev.GITHUB_OWNER}/${prev.GITHUB_REPO}`,
        emoji: true
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Period:* ${prev.startDateStr} to ${prev.endDateStr} | *Language:* ${prev.SUMMARY_LANGUAGE}\n*Activity:* ${prev.stats.commitsCount} commits, ${prev.stats.prsCount} merged PRs, ${prev.stats.issuesCount} closed issues`
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: narrativeText.substring(0, 2900)
      }
    }
  ]
};

return {
  ...prev,
  fullReportMarkdown,
  discordPayload: {
    content: discordContent,
    username: 'Claude Weekly Dev Summary',
    avatar_url: 'https://anthropic.com/favicon.ico'
  },
  slackPayload,
  emailSubject: `[Weekly Dev Summary] ${prev.GITHUB_OWNER}/${prev.GITHUB_REPO} (${prev.startDateStr} to ${prev.endDateStr})`,
  emailHtml: `<h2>${titleHeader}</h2><div style="font-family:sans-serif;line-height:1.6;"><pre style="white-space:pre-wrap;background:#f6f8fa;padding:16px;border-radius:6px;">${narrativeText}</pre></div>`
};
